255	  // Wait for the port to be LISTENing before launching the debugger (it does not
256	  // retry the bitbang connect). Numeric ports only; a non-numeric --gdb-port
257	  // (atoi -> 0) skips the wait and lets the engine reject it. Best-effort: warn
258	  // but launch anyway if it never appears.
259	  if (const int pnum = std::atoi(jtag_port.c_str());
260	      pnum > 0 && !wait_for_jtag_port(static_cast<uint16_t>(pnum)))
261	    std::fprintf(stderr,
262	                 "[andesim] --gdb: warning: vsim JTAG port %s not LISTENing "
263	                 "after 20s; launching the debugger anyway\n",
264	                 jtag_port.c_str());
265	  // -I virtual_dmi.cfg selects ICEman's remote_bitbang interface (host
266	  // localhost, port 9104) instead of its default real-hardware adapter; without
267	  // it ICEman finds no adapter and exits. The cfg is found relative to the cwd
268	  // (repo root) in interface/; it pins port 9104, matching --jtag-port's default.
269	  return exec_passthrough({iceman, "-Z", "v5", "-I", "virtual_dmi.cfg"});
270	}
