313	// `run --mode hybrid`: orchestrate a QEMU1 fast-forward -> vsim measure+drain
314	// handoff (no QEMU2). The trigger (marker|pc) delimits the ROI; the cycle figure
315	// is the vsim mcycle minus QEMU1's drained mcycle. --dry-run prints the exact
316	// per-leg command lines run_plan assembled and spawns nothing; --verify lands as
317	// the feature grows.
318	int run_hybrid(const Cli& cli) {
319	  auto fail = [](const std::string& msg) {
320	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", msg.c_str());
321	    return 2;
322	  };
323	
324	  if (int rc = check_one_elf(cli, "hybrid")) return rc;
325	
326	  // Resolve to an absolute, existing ELF through the shared resolver -- the same
327	  // "ELF not found" check fast/cycle get -- BEFORE trigger resolution, so a
328	  // missing file fails as "ELF not found" rather than a trigger error, and
329	  // before pc-boundary resolution reads the ELF's .symtab.
330	  const std::string elf = abs_elf(cli.positional[0], "--mode hybrid");
331	  if (elf.empty()) return 2;
332	
333	  std::string err;
334	  const Trigger trig = hybrid_trigger(cli, elf, err);
335	  if (!err.empty()) return fail(err);
336	
337	  // --mem-size sizes the shared mmap (= QEMU backend = vsim window); the 2 GiB
338	  // cap + ELF-fit reject ride the V-scratch work. Empty spec keeps the default.
339	  long long mem = 128LL * 1024 * 1024;  // shared mmap; --mem-size overrides
340	  if (!cli.mem_size.empty()) {
341	    std::string se;
342	    mem = parse_size(cli.mem_size, se);
343	    if (!se.empty()) return fail("--mem-size: " + se);
344	  }
345	
346	  // qemu is the built-in fast leg; resolve the accurate (vsim) leg by --engine
347	  // or the sole cycle-accurate engine (reusing the F8 selector).
348	  Discovery disc = discover_engines();
349	  const EngineDescriptor* acc =
350	      resolve_accurate_engine(disc.engines, cli.engine, err);
351	  if (!acc) {
352	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", err.c_str());
353	    for (const std::string& w : disc.warnings)
354	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
355	    return 2;
356	  }
357	
358	  Plan plan;
359	  plan.elf = elf;
360	  plan.mem_size = mem;
361	  Step qemu_step{"qemu", "fast-leg", trig};
362	  Step vsim_step{acc->id, "accurate-leg", trig};
363	  // The driver consumes only the vsim mcycle delta, so ask the accurate leg to
364	  // drain just the counters and skip the full register-file readback (~190 DM
365	  // abstract commands). Policy lives here at the Step-construction site.
366	  vsim_step.extra_args.push_back("--drain-minimal");
367	  plan.steps = {qemu_step, vsim_step};
368	
369	  // Banner to stderr so the window-cycle result stands alone on stdout.
370	  const std::string fixture = fs::path(elf).stem().string();
371	  std::fprintf(stderr, "[andesim] model=hybrid engine=%s trigger=%s fixture=%s\n",
372	               acc->id.c_str(), trig.kind.c_str(), fixture.c_str());
373	
374	  PlanOptions opts;
375	  opts.dry_run = cli.dry_run;
376	  const PlanResult r = run_plan(plan, disc.engines, opts);
377	  if (!r.ok()) {
378	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", r.error.c_str());
379	    return 1;
380	  }
381	  // --dry-run: print the exact per-leg commands run_plan assembled -- the QEMU
382	  // fast leg then the vsim accurate leg -- and stop. Nothing was spawned.
383	  if (cli.dry_run) {
384	    std::vector<std::string> labels;
385	    labels.reserve(plan.steps.size());
386	    for (const Step& s : plan.steps)
387	      labels.push_back(s.role + " [" + s.engine_id + "]");
388	    return print_dry_run(r.argvs, labels);
389	  }
390	  // Relay each leg's stdout: the program's own prints (QEMU1 phase-1 output,
391	  // then anything the ROI wrote on vsim) belong to the user. The vsim
392	  // (accurate) leg's output is prefixed by vsim's startup banner (Copyright /
393	  // Version) -- strip it so only real program output shows, the same as `cycle`
394	  // does; its [info] log is already absent (the leg's stderr was dropped at
395	  // capture). The QEMU leg has no banner, so it relays verbatim.
396	  for (size_t i = 0; i < r.phases.size(); ++i) {
397	    const std::string& out = r.phases[i].out;
398	    if (out.empty()) continue;
399	    if (i < plan.steps.size() && plan.steps[i].role == "accurate-leg") {
400	      const std::string shown = strip_vsim_banner(out);
401	      std::fwrite(shown.data(), 1, shown.size(), stdout);
402	    } else {
403	      std::fwrite(out.data(), 1, out.size(), stdout);
404	    }
405	  }
406	  // phases[0] = QEMU1 drain, [1] = vsim drain; the window figure is the vsim
407	  // mcycle delta.
408	  const unsigned long long q_mc = r.phases[0].mcycle;
409	  const unsigned long long v_mc = r.phases[1].mcycle;
410	  std::printf("[%s window_cycles] %llu  (vsim mcycle=%llu - qemu mcycle=%llu)\n",
411	              trig.kind.c_str(), v_mc - q_mc, v_mc, q_mc);
412	  std::printf("PASS: --mode hybrid --trigger %s (%s)\n", trig.kind.c_str(),
413	              fixture.c_str());
414	  return 0;
415	}
