419	int cmd_run(const Cli& cli) {
420	  if (cli.model.empty()) {
421	    std::fprintf(stderr,
422	                 "andesim run: --mode fast|cycle|hybrid is required "
423	                 "(pick the composition; see 'andesim run --help')\n");
424	    return 2;
425	  }
426	  if (!find_model(cli.model)) {
427	    std::fprintf(stderr,
428	                 "andesim run: unknown model '%s' (want fast|cycle|hybrid)\n",
429	                 cli.model.c_str());
430	    return 2;
431	  }
432	  if (!cli.gdb_port.empty() && !cli.gdb) {
433	    std::fprintf(stderr, "andesim run: --gdb-port requires --gdb\n");
434	    return 2;
435	  }
436	  // --gdb is an interactive debugging aid; the hybrid handoff runs QEMU1 then
437	  // vsim sequentially in a pipeline and cannot pause for a debugger to attach.
438	  if (cli.gdb && cli.model == "hybrid") {
439	    std::fprintf(stderr,
440	                 "andesim run: --gdb is not supported with --mode hybrid\n");
441	    return 2;
442	  }
443	  // Post-`--` args are forwarded verbatim to the engine -- but hybrid has TWO
444	  // legs (a QEMU fast-forward + a vsim measure leg) whose command lines the
445	  // handoff builds itself, so there is no single "the engine" to forward to.
446	  // Reject rather than silently drop (the old behavior) or guess a leg. vsim
447	  // options have dedicated flags (--kanata/--objdump); fast/cycle still forward.
448	  if (!cli.passthrough.empty() && cli.model == "hybrid") {
449	    std::fprintf(stderr,
450	                 "andesim run: --mode hybrid takes no `-- <args>` (the handoff "
451	                 "builds both legs' command lines; use --kanata/--objdump for "
452	                 "vsim options, or --mode fast|cycle to forward to one engine)\n");
453	    return 2;
454	  }
455	  // --trigger / --pc-start / --pc-end delimit the hybrid ROI window. --trigger
456	  // is hybrid-only; --pc-start/--pc-end belong to --trigger pc specifically. Any
457	  // other mode/trigger would SILENTLY drop them and hand back a figure for the
458	  // wrong window (fast/cycle: the whole program; hybrid+marker: the marker
459	  // window), so reject instead of measuring something the user did not ask for.
460	  if (!cli.trigger.empty() && cli.model != "hybrid") {
461	    std::fprintf(stderr,
462	                 "andesim run: --trigger applies only to --mode hybrid "
463	                 "(the ROI delimiter); fast/cycle run the whole program\n");
464	    return 2;
465	  }
466	  if (!cli.pc_end.empty() && cli.trigger != "pc") {
467	    std::fprintf(stderr,
468	                 "andesim run: --pc-end applies only to --mode hybrid "
469	                 "--trigger pc\n");
470	    return 2;
471	  }
472	  if (!cli.pc_start.empty() && cli.trigger != "pc") {
473	    std::fprintf(stderr,
474	                 "andesim run: --pc-start applies only to --mode hybrid "
475	                 "--trigger pc\n");
476	    return 2;
477	  }
478	  if (cli.model == "fast") return run_fast(cli);
479	  if (cli.model == "cycle") return run_accurate(cli);
480	  return run_hybrid(cli);  // model validated above; only hybrid remains
481	}
