1	// Reader for a drained hybrid_state_v1 file -- the C++ analog of
2	// orchestrator.abi.validate_state_file + hsim._read_state_mcycle. Header-only:
3	// it #includes the shared ABI directly, so mcycle/minstret/flags/vlenb are
4	// struct members with no hand-copied offsets.
5	#ifndef ANDESIM_STATE_HPP
6	#define ANDESIM_STATE_HPP
