9	#include <vector>
10	#include <string>
11	
12	#include "hybrid/state_abi.h"
13	
14	namespace andes_sim {
15	
16	struct StateFile {
17	  hybrid_state_v1 st{};
18	  std::string error;  // empty => valid; non-empty describes the rejection
19	  bool ok() const { return error.empty(); }
20	};
21	
22	// Read `path` and validate it (in order): byte size == sizeof(hybrid_state_v1),
23	// magic == HYBRID_STATE_MAGIC, version == HYBRID_STATE_VERSION. On any failure
24	// `error` is set and `st` is unspecified; otherwise `st` holds the full state.
25	inline StateFile read_state_file(const std::string& path) {
26	  StateFile r;
27	  std::FILE* f = std::fopen(path.c_str(), "rb");
28	  if (!f) {
29	    r.error = path + ": cannot open";
30	    return r;
31	  }
32	  std::fseek(f, 0, SEEK_END);
33	  const long sz = std::ftell(f);
34	  std::rewind(f);
35	  if (sz != static_cast<long>(sizeof(hybrid_state_v1))) {
36	    r.error = path + ": size " + std::to_string(sz) + " != expected " +
37	              std::to_string(sizeof(hybrid_state_v1));
38	    std::fclose(f);
39	    return r;
40	  }
41	  const size_t n = std::fread(&r.st, 1, sizeof(r.st), f);
42	  std::fclose(f);
43	  if (n != sizeof(r.st)) {
44	    r.error = path + ": short read";
45	    return r;
46	  }
47	
48	  char buf[256];
49	  if (r.st.magic != HYBRID_STATE_MAGIC) {
50	    std::snprintf(buf, sizeof(buf), "%s: magic 0x%08x != expected 0x%08x",
51	                  path.c_str(), r.st.magic, HYBRID_STATE_MAGIC);
52	    r.error = buf;
53	    return r;
54	  }
55	  if (r.st.version != HYBRID_STATE_VERSION) {
56	    std::snprintf(buf, sizeof(buf), "%s: version %u != expected %u",
57	                  path.c_str(), r.st.version, HYBRID_STATE_VERSION);
58	    r.error = buf;
59	    return r;
60	  }
61	  return r;
62	}
63	
64	}  // namespace andes_sim
65	
66	#endif  // ANDESIM_STATE_HPP
