90	PlanResult run_plan(const Plan& plan,
91	                    const std::vector<EngineDescriptor>& engines,
92	                    const PlanOptions& opts) {
93	  PlanResult res;
94	  if (plan.steps.empty()) {
95	    res.error = "plan has no steps";
96	    return res;
97	  }
98	
99	  // Acquire the shared mmap: allocate one under /dev/shm (and own it) when the
100	  // caller pinned none, so QEMU1's guest memory survives into the vsim leg.
101	  std::string mmap_path = plan.mmap_path;
102	  const bool own_mmap = mmap_path.empty();
103	  if (own_mmap) {
104	    std::string err;
105	    mmap_path = allocate(plan.mem_size, err);
106	    if (mmap_path.empty()) {
107	      res.error = err;
108	      return res;
109	    }
110	  }
111	
112	  // A private dir for the per-leg drain files each leg writes via {state_out}.
113	  std::error_code ec;
114	  fs::path workdir = fs::temp_directory_path(ec) / "andesim-plan-XXXXXX";
115	  std::string tmpl = workdir.string();
116	  std::vector<char> tbuf(tmpl.begin(), tmpl.end());
117	  tbuf.push_back('\0');
118	  const char* made = ::mkdtemp(tbuf.data());
119	  if (!made) {
120	    if (own_mmap) ::unlink(mmap_path.c_str());
121	    res.error = "failed to create plan work dir";
122	    return res;
123	  }
124	  const std::string wd = made;
125	
126	  RuntimeCtx ctx;
127	  ctx.mmap_path = mmap_path;
128	  ctx.mem_size = plan.mem_size;
129	  ctx.plugin_path = resolve_plugin(opts.plugin_path);  // mmap_base keeps "0x0"
130	
131	  std::string err;
132	  const std::vector<std::vector<std::string>> argvs =
133	      plan_argvs(plan, engines, wd, ctx, err);
134	  if (!err.empty()) {
135	    res.error = err;
136	  } else if (opts.dry_run) {
137	    // Build-only: the argvs are fully resolved (placeholders, threaded state
138	    // paths) -- record them for the caller to print, spawn none.
139	    res.argvs = argvs;
140	  } else {
141	    res.argvs = argvs;
142	    for (size_t i = 0; i < argvs.size(); ++i) {
143	      const RunResult r = run_process(argvs[i], opts.timeout_ms);
144	      if (r.spawn_failed) {
145	        res.error = "plan step " + std::to_string(i) + ": failed to spawn";
146	        break;
147	      }
148	      if (r.timed_out) {
149	        res.error = "plan step " + std::to_string(i) + ": timed out after " +
150	                    std::to_string(opts.timeout_ms) + " ms";
151	        break;
152	      }
153	      if (r.rc != opts.expect_rc) {
154	        res.error = "plan step " + std::to_string(i) + ": expected exit " +
155	                    std::to_string(opts.expect_rc) + ", got " +
156	                    std::to_string(r.rc);
157	        break;
158	      }
159	      // Read back this leg's drained state; the hybrid cycle figure is the
160	      // vsim-leg mcycle minus the qemu-leg mcycle. The leg's captured stdout
161	      // (r.out) rides along so the caller can relay the program's own output.
162	      const StateFile sf = read_state_file(state_path(wd, i));
163	      if (!sf.ok()) {
164	        res.error = "plan step " + std::to_string(i) + ": " + sf.error;
165	        break;
166	      }
167	      res.phases.push_back({sf.st.mcycle, sf.st.minstret, r.out});
168	    }
169	  }
170	
171	  fs::remove_all(wd, ec);
172	  if (own_mmap) ::unlink(mmap_path.c_str());
173	  return res;
174	}
175	
176	}  // namespace andes_sim
