// Oracle differential compare (verify_oracle F2): field-wise diff of two
// drained hybrid_state_v1 records -- the QEMU oracle's exit-boundary drain
// (ref) against the hybrid run's vsim drain (got).
//
// Compare policy, fixed by what vsim's drain freshly reads (state_drain.hpp
// drain_with_passthrough):
//   strict:  magic/version/flags/hart_id/priv (identity), pc, gpr[0..31];
//            fpr[0..31] under FLAG_FP; vstart/vtype/vl/vlenb/vxsat/vxrm/vcsr
//            and the vreg bytes under FLAG_V.
//   skipped: mstatus, mepc, mtvec, mcause, mtval, mscratch, medeleg,
//            mideleg, mip, mie, satp, pmpcfg[], pmpaddr[] -- passthrough on
//            the vsim side (copied from QEMU1's ENTRY snapshot, never
//            re-read), so comparing them would test entry-vs-exit.
//   masked:  mcycle, minstret -- the engines count cycles/insns differently
//            by design.
//
// This is the minimal v2 base slice: the round-trip M-mode CSRs (mscratch,
// mepc/mcause/mtval/mie), fcsr, and the Andes/M-ext/L2C/write-mask blocks each
// join the compare set alongside their own transport leg in later commits.
#ifndef ANDESIM_STATE_DIFF_HPP
#define ANDESIM_STATE_DIFF_HPP

#include <string>
#include <vector>

#include "hybrid/state_abi.h"

namespace andes_sim {

// One strictly-compared field that differs: "pc", "x5", "f31", "vl",
// "v3[7]" (register + byte offset), "flags", ...
struct FieldDiff {
  std::string field;
  unsigned long long ref = 0;
  unsigned long long got = 0;
};

struct DiffReport {
  int compared = 0;  // count of strictly compared fields
  std::vector<FieldDiff> diffs;
  bool ok() const { return diffs.empty(); }
};

DiffReport diff_states(const hybrid_state_v1& ref, const hybrid_state_v1& got);

// Print `r` as "[state-diff] ..." lines: one per mismatch, then the
// PASS/FAIL verdict. Shared by run --verify (and the e2e harness's VERIFY hook).
void print_diff_report(const DiffReport& r);

}  // namespace andes_sim

#endif  // ANDESIM_STATE_DIFF_HPP

// Oracle differential compare. See state_diff.hpp for the policy.
#include "state_diff.hpp"

#include <cstdio>
#include <string>

namespace andes_sim {

namespace {

void cmp(DiffReport& r, const std::string& field, unsigned long long ref,
         unsigned long long got) {
  ++r.compared;
  if (ref != got) r.diffs.push_back({field, ref, got});
}

}  // namespace

DiffReport diff_states(const hybrid_state_v1& ref, const hybrid_state_v1& got) {
  DiffReport r;

  cmp(r, "magic", ref.magic, got.magic);
  cmp(r, "version", ref.version, got.version);
  cmp(r, "flags", ref.flags, got.flags);
  cmp(r, "hart_id", ref.hart_id, got.hart_id);
  cmp(r, "priv", ref.priv, got.priv);
  cmp(r, "pc", ref.pc, got.pc);

  for (int i = 0; i < 32; ++i)
    cmp(r, "x" + std::to_string(i), ref.gpr[i], got.gpr[i]);

  if (ref.flags & HYBRID_FLAG_FP)
    for (int i = 0; i < 32; ++i)
      cmp(r, "f" + std::to_string(i), ref.fpr[i], got.fpr[i]);

  if (ref.flags & HYBRID_FLAG_V) {
    cmp(r, "vstart", ref.vstart, got.vstart);
    cmp(r, "vtype", ref.vtype, got.vtype);
    cmp(r, "vl", ref.vl, got.vl);
    cmp(r, "vlenb", ref.vlenb, got.vlenb);
    cmp(r, "vxsat", ref.vxsat, got.vxsat);
    cmp(r, "vxrm", ref.vxrm, got.vxrm);
    cmp(r, "vcsr", ref.vcsr, got.vcsr);

    // One compared "field" per vector register; report the first differing
    // byte as "v<i>[<byte>]".
    for (int i = 0; i < 32; ++i) {
      ++r.compared;
      const uint8_t* a = &ref.vreg[static_cast<size_t>(i) * HYBRID_VLEN_BYTES_MAX];
      const uint8_t* b = &got.vreg[static_cast<size_t>(i) * HYBRID_VLEN_BYTES_MAX];
      for (int j = 0; j < HYBRID_VLEN_BYTES_MAX; ++j) {
        if (a[j] != b[j]) {
          r.diffs.push_back({"v" + std::to_string(i) + "[" +
                                 std::to_string(j) + "]",
                             a[j], b[j]});
          break;
        }
      }
    }
  }

  return r;
}

void print_diff_report(const DiffReport& r) {
  for (const FieldDiff& d : r.diffs)
    std::printf("[state-diff] %s: ref=0x%llx got=0x%llx\n", d.field.c_str(),
                d.ref, d.got);
  if (r.ok()) {
    std::printf(
        "[state-diff] PASS: %d fields match (counters and passthrough CSRs "
        "excluded)\n",
        r.compared);
  } else {
    std::printf("[state-diff] FAIL: %zu mismatch(es) (%d fields compared)\n",
                r.diffs.size(), r.compared);
  }
}

}  // namespace andes_sim

// Unit tests for the oracle differential compare (driver/state_diff.hpp).
//
// Policy under test (verify_oracle F2): strictly compare what vsim's exit
// drain freshly reads (pc, GPRs; FPRs under FLAG_FP; V CSRs + vreg bytes
// under FLAG_V) plus the identity fields; SKIP the passthrough M-CSRs/PMP
// (vsim copies them from QEMU1's entry snapshot, so they cannot equal the
// oracle's exit values by construction); MASK the counters (engines count
// differently by design). This is the minimal v2 base slice -- the round-trip
// M-mode CSRs, fcsr, and the Andes/M-ext/L2C blocks join later.
#include "state_diff.hpp"

#include "hybrid/state_abi.h"
#include "test_check.hpp"

using namespace andes_sim;

namespace {

// A fully populated reference state (FP + V live).
hybrid_state_v1 base_state() {
  hybrid_state_v1 s{};
  s.magic = HYBRID_STATE_MAGIC;
  s.version = HYBRID_STATE_VERSION;
  s.flags = HYBRID_FLAG_RV64 | HYBRID_FLAG_FP | HYBRID_FLAG_V;
  s.hart_id = 0;
  s.priv = 3;
  s.pc = 0x100240;
  for (int i = 0; i < 32; ++i) s.gpr[i] = 0x1000 + i;
  s.gpr[0] = 0;
  for (int i = 0; i < 32; ++i) s.fpr[i] = 0x2000 + i;
  s.vstart = 0;
  s.vtype = 0xd0;
  s.vl = 16;
  s.vlenb = 64;
  s.vxsat = 0;
  s.vxrm = 1;
  s.vcsr = 2;
  for (int i = 0; i < 32 * HYBRID_VLEN_BYTES_MAX; ++i)
    s.vreg[i] = static_cast<uint8_t>(i * 7);
  s.mcycle = 1000;
  s.minstret = 900;
  s.mstatus = 0xa00002200ull;
  s.mepc = 0x5555;
  s.satp = 0x9999;
  s.pmpaddr[3] = 0x77;
  return s;
}

// Fields strictly compared for a FP+V state (v2 base slice): 6 identity/pc +
// 32 gpr + 32 fpr + 7 V scalars + 32 vregs.
constexpr int kFullCompared = 6 + 32 + 32 + 7 + 32;

}  // namespace

int main() {
  {  // identical states -> ok, full field count
    const hybrid_state_v1 a = base_state();
    const DiffReport r = diff_states(a, a);
    CHECK(r.ok());
    CHECK(r.compared == kFullCompared);
  }

  {  // a GPR mismatch is caught and named (the one-divergence base case)
    const hybrid_state_v1 ref = base_state();
    hybrid_state_v1 got = ref;
    got.gpr[5] = 0xdead;
    const DiffReport r = diff_states(ref, got);
    CHECK(!r.ok());
    CHECK(r.diffs.size() == 1);
    CHECK(r.diffs[0].field == "x5");
    CHECK(r.diffs[0].ref == 0x1005);
    CHECK(r.diffs[0].got == 0xdead);
  }

  {  // pc mismatch
    const hybrid_state_v1 ref = base_state();
    hybrid_state_v1 got = ref;
    got.pc = ref.pc + 4;
    const DiffReport r = diff_states(ref, got);
    CHECK(r.diffs.size() == 1);
    CHECK(r.diffs[0].field == "pc");
  }

  {  // counters are masked: mcycle/minstret may differ
    const hybrid_state_v1 ref = base_state();
    hybrid_state_v1 got = ref;
    got.mcycle = 999999;
    got.minstret = 888888;
    CHECK(diff_states(ref, got).ok());
  }

  {  // passthrough M-CSRs/PMP are skipped, not compared (v2 base slice: the
     // round-trip M-mode CSRs join the compare set with their transport legs)
    const hybrid_state_v1 ref = base_state();
    hybrid_state_v1 got = ref;
    got.mstatus = 0x1;
    got.mepc = 0x2;
    got.mtvec = 0x3;
    got.mcause = 0x4;
    got.mtval = 0x5;
    got.mscratch = 0x6;
    got.medeleg = 0x7;
    got.mideleg = 0x8;
    got.mip = 0x9;
    got.mie = 0xa;
    got.satp = 0xb;
    got.pmpcfg[0] = 0xc;
    got.pmpaddr[63] = 0xd;
    CHECK(diff_states(ref, got).ok());
  }

  {  // no FLAG_FP -> FPRs not compared, count shrinks
    hybrid_state_v1 ref = base_state();
    ref.flags = HYBRID_FLAG_RV64;
    hybrid_state_v1 got = ref;
    got.fpr[7] = 0xbad;
    got.vtype = 0xbad;  // V block also off
    const DiffReport r = diff_states(ref, got);
    CHECK(r.ok());
    CHECK(r.compared == 6 + 32);
  }

  {  // FPR mismatch under FLAG_FP
    const hybrid_state_v1 ref = base_state();
    hybrid_state_v1 got = ref;
    got.fpr[31] = 0;
    const DiffReport r = diff_states(ref, got);
    CHECK(r.diffs.size() == 1);
    CHECK(r.diffs[0].field == "f31");
  }

  {  // V scalar CSR mismatch
    const hybrid_state_v1 ref = base_state();
    hybrid_state_v1 got = ref;
    got.vl = 8;
    const DiffReport r = diff_states(ref, got);
    CHECK(r.diffs.size() == 1);
    CHECK(r.diffs[0].field == "vl");
  }

  {  // vreg byte mismatch names the register and byte offset
    const hybrid_state_v1 ref = base_state();
    hybrid_state_v1 got = ref;
    got.vreg[3 * HYBRID_VLEN_BYTES_MAX + 7] ^= 0xff;
    const DiffReport r = diff_states(ref, got);
    CHECK(r.diffs.size() == 1);
    CHECK(r.diffs[0].field == "v3[7]");
    CHECK(r.diffs[0].ref == ref.vreg[3 * HYBRID_VLEN_BYTES_MAX + 7]);
  }

  {  // identity mismatch (flags) is caught
    const hybrid_state_v1 ref = base_state();
    hybrid_state_v1 got = ref;
    got.flags = HYBRID_FLAG_RV64;
    const DiffReport r = diff_states(ref, got);
    CHECK(!r.ok());
    bool saw_flags = false;
    for (const FieldDiff& d : r.diffs) saw_flags |= d.field == "flags";
    CHECK(saw_flags);
  }

  {  // multiple mismatches all reported
    const hybrid_state_v1 ref = base_state();
    hybrid_state_v1 got = ref;
    got.gpr[1] = 1;
    got.gpr[2] = 2;
    got.pc = 4;
    CHECK(diff_states(ref, got).diffs.size() == 3);
  }

  return andes_sim::test::report("state_diff");
}

